import{_ as t,o,c as a,a2 as r}from"./chunks/framework.BGlkWkwp.js";const m=JSON.parse('{"title":"Swatch","description":"","frontmatter":{},"headers":[],"relativePath":"components/swatch.md","filePath":"components/swatch.md"}'),c={name:"components/swatch.md"};function d(s,e,i,n,h,l){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="swatch" tabindex="-1">Swatch <a class="header-anchor" href="#swatch" aria-label="Permalink to &quot;Swatch&quot;">​</a></h1><p>Swatch shows a sample of a color.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to use&quot;">​</a></h2><p>Use it beside a name in a list, a key of colors or the trigger of a color picker; to choose a color, use a <a href="./color-picker">ColorPicker</a>. The shape tells the kind of thing drawn: <code>box</code> a filled square, <code>dot</code> a point, <code>line</code> a segment, <code>area</code> a small square with a line, <code>ramp</code> a continuous scheme (pass a gradient as <code>color</code>) and <code>icon</code> a tool&#39;s glyph in the color. A swatch that is pressed goes inside an icon <a href="./button">Button</a>.</p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Prop</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>color</code></td><td>required</td><td>A CSS color, or a gradient for <code>ramp</code></td></tr><tr><td><code>shape</code></td><td><code>box</code></td><td><code>box</code>, <code>dot</code>, <code>line</code>, <code>area</code>, <code>ramp</code> or <code>icon</code></td></tr><tr><td><code>icon</code></td><td></td><td>The glyph for <code>icon</code> (a name or a component)</td></tr><tr><td><code>fill</code></td><td><code>false</code></td><td>Stretches to the width of its container</td></tr></tbody></table><h2 id="contract" tabindex="-1">Contract <a class="header-anchor" href="#contract" aria-label="Permalink to &quot;Contract&quot;">​</a></h2><p>The box is the square of an icon with a line inside, so that a pale color keeps its edge without growing the mark; the other shapes have fixed sizes in rem. The glyph of <code>icon</code> is drawn over a halo of the same glyph, thicker, in line-strong. The color is a value of the content and is the one style a component takes (<code>--kata-swatch-color</code>). A swatch is hidden from screen readers; the text beside it names it.</p><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to &quot;Example&quot;">​</a></h2><figure class="kata-example"><iframe src="/kata/examples/swatch/" title="Swatch" loading="lazy" style="width:100%;height:32rem;border:1px solid var(--vp-c-divider);border-radius:8px;"></iframe><figcaption><a href="/kata/examples/swatch/" target="_blank" rel="noopener">Swatch</a></figcaption></figure>',10)])])}const f=t(c,[["render",d]]);export{m as __pageData,f as default};
